import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { existsSync, readdirSync, readFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { generatorFiles, gitBlobSha1, scanDomText, validateProvenance } from './provenance.ts'
import { screenshotLocales, validateMapping } from './steps.ts'

// USER-GUIDE-01 UG-DOC-03: every committed screenshot was generated by the capture script from the
// synthetic lab tenant, its captured DOM text holds no e-mail/IMO/password/token pattern and no other
// tenant, and the provenance hash matches the committed PNG. UG-DOC-02: one file per captured step.
const folder = resolve(import.meta.dirname, '../../../frontend/src/help/screenshots')
const mapping = validateMapping(JSON.parse(readFileSync(resolve(folder, 'steps.json'), 'utf8')))
const root = resolve(import.meta.dirname, '../../..')
// QA N3: the committed generator files must be exactly the ones the screenshots were produced with.
const generatorBlobs = Object.fromEntries(generatorFiles.map(path => [path, gitBlobSha1(readFileSync(resolve(root, path)))]))

test('every captured step of every committed viewport has a PNG with valid provenance', () => {
  let count = 0
  for (const locale of screenshotLocales) for (const [key, guide] of Object.entries(mapping.guides)) for (const step of guide.steps) {
    if (step.unavailable) continue
    for (const viewport of mapping.committedViewports) {
      const base = resolve(folder, locale, key, `${step.step}-${viewport}`)
      assert.ok(existsSync(base + '.png'), `${locale}/${key}/${step.step}-${viewport}.png missing`)
      const png = readFileSync(base + '.png')
      assert.equal(png.subarray(1, 4).toString('latin1'), 'PNG')
      const sha256 = createHash('sha256').update(png).digest('hex')
      const record = JSON.parse(readFileSync(base + '.json', 'utf8'))
      assert.deepEqual(validateProvenance(record, { key, locale, step: step.step, viewport, sha256, generatorBlobs }), [], `${locale}/${key}/${step.step}-${viewport}`)
      assert.equal(record.png.width, png.readUInt32BE(16))
      count++
    }
  }
  assert.ok(count > 0)
})

test('no PNG or provenance file exists outside the mapping', () => {
  for (const locale of readdirSync(folder, { withFileTypes: true }).filter(item => item.isDirectory()).map(item => item.name)) {
    assert.ok((screenshotLocales as readonly string[]).includes(locale), locale)
    for (const key of readdirSync(resolve(folder, locale))) {
      const guide = mapping.guides[key]
      assert.ok(guide, key)
      for (const file of readdirSync(resolve(folder, locale, key))) {
        const match = /^(\d+)-(desktop|mobile)\.(png|json)$/.exec(file)
        assert.ok(match, file)
        const step = guide.steps.find(item => item.step === Number(match[1]))
        assert.ok(step && !step.unavailable && mapping.committedViewports.includes(match[2] as 'desktop'), `${locale}/${key}/${file}`)
      }
    }
  }
})

test('the DOM-text scan reports kinds only and catches personal data, credentials and foreign tenants', () => {
  assert.deepEqual(scanDomText('Synthetic Fleet A · DEMO-SHIP · Unknown'), [])
  assert.deepEqual(scanDomText('Contact jane.doe@example.com'), ['email'])
  assert.deepEqual(scanDomText('Vessel IMO 9074729'), ['imo'])
  assert.deepEqual(scanDomText('password: hunter2'), ['password'])
  assert.deepEqual(scanDomText('Authorization: Bearer abcdefghijklmnopqrstuv'), ['bearer'])
  assert.deepEqual(scanDomText('Synthetic Ship B'), ['foreign_tenant'])
  assert.deepEqual(scanDomText('the value is s3cr3t-token-value', ['s3cr3t-token-value']), ['credential'])
  const record = { schemaVersion: 'poseidon.help.screenshot-provenance.v2', generator: 'tests/Poseidon.Browser.Tests/screenshots/capture.ts',
    commit: 'a'.repeat(40), generatorBlobs, dirty: false, key: 'today', locale: 'en', step: 1, viewport: 'desktop',
    datasets: ['backend/seed/synthetic-demo.json', 'manual upload'], tenant: 'Synthetic Fleet A', png: { sha256: 'x' }, domText: 'ok' }
  const expected = { key: 'today', locale: 'en', step: 1, viewport: 'desktop', sha256: 'x', generatorBlobs }
  assert.deepEqual(validateProvenance(record, expected), ['datasets'])
})

test('a screenshot from a dirty or different generator is rejected (QA N3)', () => {
  const base = { schemaVersion: 'poseidon.help.screenshot-provenance.v2', generator: 'tests/Poseidon.Browser.Tests/screenshots/capture.ts',
    commit: 'b'.repeat(40), generatorBlobs, dirty: false, key: 'today', locale: 'en', step: 1, viewport: 'desktop',
    datasets: ['backend/seed/synthetic-demo.json'], tenant: 'Synthetic Fleet A', png: { sha256: 'x' }, domText: 'ok' }
  const expected = { key: 'today', locale: 'en', step: 1, viewport: 'desktop', sha256: 'x', generatorBlobs }
  assert.deepEqual(validateProvenance(base, expected), [])
  assert.deepEqual(validateProvenance({ ...base, dirty: true }, expected), ['generator_dirty'])
  assert.deepEqual(validateProvenance({ ...base, dirty: undefined }, expected), ['generator_dirty'])
  const changed = { ...generatorBlobs, [generatorFiles[0]]: '0'.repeat(40) }
  assert.deepEqual(validateProvenance({ ...base, generatorBlobs: changed }, expected), ['generator_blob'])
  assert.deepEqual(validateProvenance({ ...base, generatorBlobs: {} }, expected), ['generator_blob'])
  // Git's blob id of the empty file and of a CRLF file equal the LF-normalised git hash-object result.
  assert.equal(gitBlobSha1(Buffer.alloc(0)), 'e69de29bb2d1d6434b8b29ae775ad8c2e48c5391')
  assert.equal(gitBlobSha1(Buffer.from('a\r\nb\n')), gitBlobSha1(Buffer.from('a\nb\n')))
})
